<?php

// ------------------------------------------------------------------------------
// Generated by Tabbit. DO NOT EDIT.
//
// The runtime, copied in beside the generated code so the output is
// self-contained. Edit it in the Tabbit repository, not here: this file is
// rewritten on every run, and the header above is what lets a later run remove
// it if it ever moves.
// ------------------------------------------------------------------------------

/**
 * Tabbit's data updater.
 *
 * Brings a local copy of the exported data up to date with a copy served over HTTP - a
 * CDN, a bucket, a patch server - so a running program can take new data without being
 * redeployed. Emitted beside the reader and reads nothing but the manifest, so it knows
 * nothing about the schema and never has to change when one does.
 *
 * The manifest is what the exporter already writes next to the data: one entry per file
 * with its size and MD5. Comparing it with the local copy is the whole of the diff, so a
 * run downloads what changed and nothing else.
 *
 * Three properties, because a patcher that fails badly is worse than one that does not
 * exist:
 *
 *   Nothing is replaced until everything has arrived and been checked. Files land in a
 *   staging directory first and the local manifest is written last, so an update killed
 *   halfway leaves the previous data readable and the next run redoes the difference.
 *
 *   Every file is checked against the hash the manifest gives for it, so a truncated
 *   transfer that a proxy reported as success does not reach the cache.
 *
 *   A transient failure is retried with a doubling backoff, and a permanent one is not.
 *
 * Reading is somebody else's job. This produces a directory, and the generated tables
 * read it.
 *
 * PHP's own functions and no extension: the HTTP stream wrapper for the transfer,
 * `json_decode` and `md5` for the rest. Not `ext-curl`, which reads better and is not
 * always compiled in - this was written against it first, and the interpreter that ran
 * the gate answered `Call to undefined function curl_init()`. The wrapper needs
 * `allow_url_fopen`, which is on by default; the language guide says so.
 */

declare(strict_types=1);

namespace Tabbit;

/** What an update is allowed to do. Every value has a working default. */
final class UpdateOptions
{
    /**
     * The binary exporter writes manifest-binary.json; the JSON exporter writes
     * manifest-json.json.
     */
    public string $manifestFileName = 'manifest-binary.json';

    /** The first attempt is included, so three is two retries. */
    public int $maxAttempts = 3;

    /** Seconds before the second attempt. Doubled for each attempt after it. */
    public float $retryDelay = 0.5;

    public float $requestTimeout = 30.0;
    public bool $verifyHash = true;

    /** @var null|callable(string):void Called with one line of progress, when set. */
    public $log = null;
}

/** What an update did. */
final class UpdateResult
{
    public bool $succeeded = false;
    public ?string $error = null;
    public bool $upToDate = false;
    public int $downloadedCount = 0;
    public int $downloadedBytes = 0;
    public int $deletedCount = 0;

    /**
     * The directory holding the data. Hand it to the generated accessor's readAll. Set even
     * on failure, because the previous data is still there and still readable - which is
     * the point of failing the way this does.
     */
    public string $localPath;

    public function __construct(string $localPath)
    {
        $this->localPath = $localPath;
    }
}

/** One file of the manifest, and the hash to check it by. */
final class ManifestEntry
{
    public function __construct(
        public readonly string $name,
        public readonly int $size,
        public readonly string $hash
    ) {
    }
}

/** A failure the same request might survive a moment later. */
final class TransientException extends \RuntimeException
{
}

final class TabbitUpdater
{
    /**
     * Brings `$cacheDirectory` up to date with the data served under `$baseUrl`.
     *
     * Does not throw. Everything that can go wrong here - the network, the disk, a file
     * that arrived corrupt - is a condition the caller has to handle rather than a defect,
     * and a patcher that throws into a service's startup is one that gets wrapped in a
     * bare catch that swallows the reason.
     */
    public static function update(
        string $baseUrl,
        string $cacheDirectory,
        ?UpdateOptions $options = null
    ): UpdateResult {
        $options ??= new UpdateOptions();
        $result = new UpdateResult($cacheDirectory);

        $log = static function (string $message) use ($options): void {
            if ($options->log !== null) {
                ($options->log)($message);
            }
        };

        try {
            $manifestText = self::download(
                self::joinUrl($baseUrl, $options->manifestFileName), $options, $log);

            $remote = self::parseManifest($manifestText);
            $local = self::readLocalManifest(
                self::localPath($cacheDirectory, $options->manifestFileName));

            $byName = [];
            foreach ($local as $entry) {
                $byName[$entry->name] = $entry;
            }

            $wanted = [];

            foreach ($remote as $entry) {
                $previous = $byName[$entry->name] ?? null;

                // The file's presence is checked as well as the manifest's word for it: a
                // cache somebody cleaned out by hand would otherwise never be refilled.
                $current = $previous !== null
                    && $previous->hash === $entry->hash
                    && \is_file(self::localPath($cacheDirectory, $entry->name));

                if (!$current) {
                    $wanted[] = $entry;
                }
            }

            $served = [];
            foreach ($remote as $entry) {
                $served[$entry->name] = true;
            }

            $gone = [];
            foreach ($local as $entry) {
                if (!isset($served[$entry->name])) {
                    $gone[] = $entry->name;
                }
            }

            if ($wanted === [] && $gone === []) {
                $log('tabbit: already up to date.');

                $result->succeeded = true;
                $result->upToDate = true;
                return $result;
            }

            $log(\sprintf('tabbit: %d file(s) to fetch, %d to remove.',
                \count($wanted), \count($gone)));

            // Everything lands here first. Nothing the caller can read is touched until the
            // last file has arrived and been checked.
            $staging = self::localPath($cacheDirectory, '.staging');

            self::makeDirectory($cacheDirectory);
            self::deleteRecursively($staging);
            self::makeDirectory($staging);

            foreach ($wanted as $entry) {
                $data = self::download(self::joinUrl($baseUrl, $entry->name), $options, $log);

                if ($options->verifyHash && $entry->hash !== '') {
                    $actual = \md5($data);

                    if (\strcasecmp($actual, $entry->hash) !== 0) {
                        throw new \RuntimeException(\sprintf(
                            "'%s' arrived with hash %s, and the manifest says %s. "
                            . 'Nothing was replaced.',
                            $entry->name, $actual, $entry->hash));
                    }
                }

                $staged = self::localPath($staging, $entry->name);

                self::makeDirectory(\dirname($staged));
                self::writeFile($staged, $data);

                $result->downloadedBytes += \strlen($data);
            }

            // From here on the update is applied. Nothing below reaches the network.
            foreach ($gone as $name) {
                $target = self::localPath($cacheDirectory, $name);

                if (\is_file($target)) {
                    \unlink($target);
                }

                $result->deletedCount += 1;
            }

            foreach ($wanted as $entry) {
                $target = self::localPath($cacheDirectory, $entry->name);

                self::makeDirectory(\dirname($target));

                if (\is_file($target)) {
                    \unlink($target);
                }

                if (!@\rename(self::localPath($staging, $entry->name), $target)) {
                    throw new \RuntimeException("'{$entry->name}' could not be moved into place.");
                }

                $result->downloadedCount += 1;
            }

            // Last, and that ordering is the recovery story: a run killed before this point
            // leaves a manifest describing the data that is still on disk, so the next run
            // fetches the same files again rather than believing it has them.
            self::writeFile(
                self::localPath($cacheDirectory, $options->manifestFileName), $manifestText);

            self::deleteRecursively($staging);

            $log(\sprintf('tabbit: updated. %d fetched, %d removed.',
                $result->downloadedCount, $result->deletedCount));

            $result->succeeded = true;
            return $result;
        } catch (\Throwable $error) {
            // The previous data is untouched, so the caller can carry on with it.
            $result->error = $error->getMessage();

            $log('tabbit: update failed: ' . $result->error);
            return $result;
        }
    }

    /**
     * Reads the entries out of a manifest's JSON.
     *
     * @return list<ManifestEntry>
     */
    public static function parseManifest(string $text): array
    {
        $manifest = \json_decode($text, true);

        if (!\is_array($manifest) || !isset($manifest['Items']) || !\is_array($manifest['Items'])) {
            throw new \RuntimeException('the manifest has no Items array');
        }

        $entries = [];

        foreach ($manifest['Items'] as $item) {
            if (!\is_array($item)) {
                continue;
            }

            $name = $item['Name'] ?? '';

            if (!\is_string($name) || $name === '') {
                continue;
            }

            $entries[] = new ManifestEntry(
                $name, (int)($item['Size'] ?? 0), (string)($item['Hash'] ?? ''));
        }

        return $entries;
    }

    // ------------------------------------------------------------------ transfer

    /** Fetches one URL, retrying what is worth retrying. */
    private static function download(string $url, UpdateOptions $options, callable $log): string
    {
        $delay = $options->retryDelay;
        $attempts = \max(1, $options->maxAttempts);

        for ($attempt = 1; ; $attempt++) {
            try {
                return self::fetch($url, $options);
            } catch (TransientException $error) {
                if ($attempt >= $attempts) {
                    throw $error;
                }

                $log(\sprintf('tabbit: %s Retrying in %.1fs (%d of %d).',
                    $error->getMessage(), $delay, $attempt, $attempts));

                \usleep((int)($delay * 1000000));

                // Doubling rather than a fixed wait: a server refusing because it is
                // overloaded is not helped by every client coming back at the same interval.
                $delay *= 2;
            }
        }
    }

    private static function fetch(string $url, UpdateOptions $options): string
    {
        $context = \stream_context_create([
            'http' => [
                'method' => 'GET',
                'timeout' => $options->requestTimeout,
                'follow_location' => 1,

                // Without this a 404 is `false` with no headers, and this has to tell a
                // 404 from a 503 to know whether retrying is worth anything.
                'ignore_errors' => true,
            ],
        ]);

        // `$http_response_header` is declared in this scope by the stream wrapper, and
        // only when a response arrived at all.
        $http_response_header = [];
        $body = @\file_get_contents($url, false, $context);

        if ($body === false) {
            // The request never got an answer - DNS, a refused connection, a timeout.
            $why = \error_get_last()['message'] ?? 'no answer';

            throw new TransientException("'{$url}' could not be reached: {$why}.");
        }

        $status = self::statusOf($http_response_header);

        if ($status >= 200 && $status < 300) {
            return $body;
        }

        $message = "'{$url}' answered {$status}.";

        // 408 and 429 are the server asking for another attempt, and 5xx is it failing on
        // its own account. A 404 is an answer: retrying it costs three round trips to hear
        // the same thing.
        if ($status === 408 || $status === 429 || ($status >= 500 && $status <= 599)) {
            throw new TransientException($message);
        }

        throw new \RuntimeException($message);
    }

    /**
     * The status code of the last response in a header list.
     *
     * The last, because a redirect the wrapper followed leaves both status lines here and
     * the one that matters is where it ended up.
     *
     * @param list<string> $headers
     */
    private static function statusOf(array $headers): int
    {
        $status = 0;

        foreach ($headers as $header) {
            if (\preg_match('#^HTTP/\S+\s+(\d{3})#', $header, $found) === 1) {
                $status = (int)$found[1];
            }
        }

        return $status;
    }

    // --------------------------------------------------------------------- disk

    /**
     * Reads the cached manifest.
     *
     * A missing or unreadable one is an empty manifest, which makes the next update fetch
     * everything - the safe direction to be wrong in.
     *
     * @return list<ManifestEntry>
     */
    private static function readLocalManifest(string $filename): array
    {
        try {
            $text = @\file_get_contents($filename);

            return $text === false ? [] : self::parseManifest($text);
        } catch (\Throwable) {
            return [];
        }
    }

    /** A manifest name resolved under a directory, with its forward slashes honoured. */
    private static function localPath(string $directory, string $name): string
    {
        return \rtrim($directory, '/\\') . \DIRECTORY_SEPARATOR
            . \str_replace('/', \DIRECTORY_SEPARATOR, $name);
    }

    private static function makeDirectory(string $directory): void
    {
        if (\is_dir($directory)) {
            return;
        }

        if (!@\mkdir($directory, 0o777, true) && !\is_dir($directory)) {
            throw new \RuntimeException("'{$directory}' could not be created.");
        }
    }

    private static function writeFile(string $filename, string $contents): void
    {
        if (@\file_put_contents($filename, $contents) === false) {
            throw new \RuntimeException("'{$filename}' could not be written.");
        }
    }

    private static function deleteRecursively(string $directory): void
    {
        if (!\is_dir($directory)) {
            return;
        }

        foreach (\scandir($directory) ?: [] as $name) {
            if ($name === '.' || $name === '..') {
                continue;
            }

            $path = $directory . \DIRECTORY_SEPARATOR . $name;

            if (\is_dir($path)) {
                self::deleteRecursively($path);
            } else {
                \unlink($path);
            }
        }

        \rmdir($directory);
    }

    /**
     * Joins a base URL and a file name.
     *
     * Not a path join, which on Windows produces a backslash and a URL no server will
     * answer.
     */
    private static function joinUrl(string $baseUrl, string $name): string
    {
        return \rtrim($baseUrl, '/') . '/' . \str_replace('\\', '/', $name);
    }
}
